import{_ as i,o as t,c as a,a4 as n}from"./chunks/framework.CcIOJJza.js";const o="/mxcad/assets/image-20260714105757048.W4Qc6qvF.png",s="/mxcad/assets/image-20260714111413977.CAKVM7iK.png",r="/mxcad/assets/image-20260714111435983.DDjTIIjy.png",l="/mxcad/assets/image-20260714112146024.BJtJbs9j.png",d="/mxcad/assets/image-20260714113736282.BOFRVcCl.png",c="/mxcad/assets/image-20260714143606665.D8aL0Dxc.png",p="/mxcad/assets/image-20260714145126854.nQRO3BZn.png",m="/mxcad/assets/image-20260714145348144.DgLNh2eI.png",g="/mxcad/assets/image-20260714145838383.BsMOn0Ox.png",h="/mxcad/assets/image-20260714150040244.Ddh3duv7.png",u="/mxcad/assets/image-20260714155252826.CyxXRTdX.png",f="/mxcad/assets/image-20260714160206324.GKRziyGf.png",A=JSON.parse('{"title":"Professional CAD in Browser: CAD Dream Online Drawing Simplifies Secondary Development","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/8.RelatedArticles/2.MxCADFunctionIntroduction/1.Professional CAD in the browser.md","filePath":"en/docs/8.RelatedArticles/2.MxCADFunctionIntroduction/1.Professional CAD in the browser.md"}'),b={name:"en/docs/8.RelatedArticles/2.MxCADFunctionIntroduction/1.Professional CAD in the browser.md"};function w(y,e,D,k,v,x){return t(),a("div",null,e[0]||(e[0]=[n('<h1 id="professional-cad-in-browser-cad-dream-online-drawing-simplifies-secondary-development" tabindex="-1">Professional CAD in Browser: CAD Dream Online Drawing Simplifies Secondary Development <a class="header-anchor" href="#professional-cad-in-browser-cad-dream-online-drawing-simplifies-secondary-development" aria-label="Permalink to &quot;Professional CAD in Browser: CAD Dream Online Drawing Simplifies Secondary Development&quot;">​</a></h1><p>Against the tide of digital transformation, the engineering design industry is undergoing profound changes shifting from &quot;local software&quot; to &quot;cloud collaboration&quot;. For numerous enterprises and developers, finding a Web-based CAD solution that can meet professional drawing demands, support flexible integration and in-depth customization has become the key to improving efficiency. CAD Dream Online Drawing is a new-generation cloud CAD platform built with cutting-edge technologies. It breaks the reliance of traditional CAD software on operating systems, allowing users to access a professional design workspace anytime and anywhere via only a browser.</p><p>CAD Dream Online Drawing Access URL: <a href="https://demo2.mxdraw3d.com:3000/mxcad/" target="_blank" rel="noreferrer">https://demo2.mxdraw3d.com:3000/mxcad/</a> Running interface of CAD Dream Online Drawing is shown below: <img src="'+o+'" alt="image-20260714105757048"></p><h2 id="i-what-is-cad-dream-online-drawing" tabindex="-1">I. What is CAD Dream Online Drawing? <a class="header-anchor" href="#i-what-is-cad-dream-online-drawing" aria-label="Permalink to &quot;I\\. What is CAD Dream Online Drawing?&quot;">​</a></h2><p>CAD Dream Online Drawing is more than a web-based drawing viewer; it is a fully functional online design and editing system. From the perspective of technical architecture, it is a CAD project deeply developed based on the powerful MxCAD Dream Control kernel combined with the modern Vue3 front-end framework.</p><p>This technical combination brings dual advantages: it possesses native-level parsing and rendering capabilities for DWG/DXF formats from the underlying graphics engine, ensuring precise reading of drawing data; meanwhile, it delivers ultra-fast response, component-based development and excellent interactive experience brought by the Vue3 framework. It marks the successful transformation of CAD applications from &quot;heavy client software&quot; to &quot;lightweight Web services&quot;.</p><h2 id="ii-zero-threshold-getting-started" tabindex="-1">II. Zero-Threshold Getting Started <a class="header-anchor" href="#ii-zero-threshold-getting-started" aria-label="Permalink to &quot;II\\. Zero\\-Threshold Getting Started&quot;">​</a></h2><p>For professional CAD users, the biggest concern when migrating from desktop to Web platforms is often not performance, but the disruption of operation habits. Fully aware of this pain point, CAD Dream Online Drawing does not blindly pursue &quot;innovation&quot; in the design of core functional modules; instead, it carries out pixel-level in-depth restoration of AutoCAD, the industry benchmark. Whether it is the visual interface or muscle-memory operation logic, it strives to make users feel &quot;this is AutoCAD running in the browser&quot;.</p><h3 id="_1-high-consistency-of-drawing-interface" tabindex="-1">1. High Consistency of Drawing Interface <a class="header-anchor" href="#_1-high-consistency-of-drawing-interface" aria-label="Permalink to &quot;1\\. High Consistency of Drawing Interface&quot;">​</a></h3><p>Upon opening CAD Dream Online Drawing, users are greeted by a highly recognizable dark immersive drawing space, identical to AutoCAD’s classic model space. <img src="'+s+'" alt="image-20260714111413977"></p><ul><li><p><strong>Classic Layout Reproduction</strong>: The top of the interface retains standard Ribbon functional menus (File, Edit, View, Draw, etc.), a command line input box and status bar (toggle switches for Snap, Ortho, Polar, etc.) at the bottom, and a detailed Properties panel on the right. This layout fully conforms to engineers’ years of visual habits, enabling users to locate required tools without re-adaptation.</p></li><li><p><strong>Coordinate System &amp; Navigation</strong>: The UCS coordinate icon at the bottom left, Model/Layout tabs at the bottom, as well as middle-mouse pan and mouse-wheel zoom logic are strictly consistent with desktop software.</p></li></ul><h3 id="_2-perfect-inheritance-of-operation-habits" tabindex="-1">2. Perfect Inheritance of Operation Habits <a class="header-anchor" href="#_2-perfect-inheritance-of-operation-habits" aria-label="Permalink to &quot;2\\. Perfect Inheritance of Operation Habits&quot;">​</a></h3><p>True restoration is not merely &quot;similar appearance&quot;, but &quot;smooth operation&quot;. CAD Dream Online Drawing fully replicates AutoCAD’s interaction logic:</p><ul><li><p><strong>Command Line Driven</strong>: It is one of the few Web systems that fully retains <strong>command line interaction</strong>. Users can directly input <code>L</code> for lines, <code>C</code> for circles, <code>TR</code> for trim, <code>M</code> for move just like in traditional CAD. This efficient keyboard operation workflow is completely preserved to guarantee undiminished drawing efficiency. <img src="'+r+'" alt="image-20260714111435983"></p></li><li><p><strong>Grip Editing &amp; Object Snap</strong>: Blue grips appear after selecting graphics, supporting quick operations such as stretch, move and rotate; object snap markers (green boxes, triangles, etc.) automatically trigger when the cursor approaches endpoints, midpoints, circle centers, with sensitivity and display styles reaching the precision standard of desktop software. <img src="'+l+'" alt="image-20260714112146024"></p></li><li><p><strong>Right-Click Menu &amp; Shortcuts</strong>: Common functions including right-click confirmation, repeat last command, and universal shortcuts such as Ctrl+C/V/Z are natively supported. <img src="'+d+'" alt="image-20260714113736282"></p></li></ul><p>Through this all-round restoration from visuals to operation experience, CAD Dream Online Drawing eliminates the gap between Web and desktop platforms, allowing senior designers to get started with zero learning cost.</p><h2 id="iii-detailed-explanation-of-each-module-function" tabindex="-1">III. Detailed Explanation of Each Module Function <a class="header-anchor" href="#iii-detailed-explanation-of-each-module-function" aria-label="Permalink to &quot;III\\. Detailed Explanation of Each Module Function&quot;">​</a></h2><p>CAD Dream Online Drawing aims to build a &quot;cloud-based AutoCAD&quot; product. Its strength lies not only in interface restoration, but also in solid and complete internal functional modules. By deeply polishing each core module, it constructs a powerful design environment that conforms to traditional workflows while retaining Web-side flexibility.</p><h3 id="_1-drawing-editing-module" tabindex="-1">1. Drawing &amp; Editing Module <a class="header-anchor" href="#_1-drawing-editing-module" aria-label="Permalink to &quot;1\\. Drawing \\&amp; Editing Module&quot;">​</a></h3><p>It reproduces desktop-level operation experience with extreme refinement for drawing and editing, the core work area of designers. <img src="'+c+'" alt="image-20260714143606665"></p><ul><li><p><strong>Full Parametric Drawing</strong>: It provides standard drawing tools including lines, polylines, circles, arcs, rectangles, regular polygons, etc. Users can input coordinates or relative distances via the command line for precise drawing, fully satisfying engineers’ pursuit of accuracy.</p></li><li><p><strong>Powerful Modification Toolset</strong>: All common modification commands are available, including Move, Copy, Rotate, Mirror, Offset, Array, Trim, Extend, Chamfer, Fillet, etc. Especially the <strong>grip editing</strong> function: blue control points appear after selecting objects, supporting direct stretch, scale or rotate with extremely sensitive interactive feedback.</p></li><li><p><strong>Intelligent Snap System</strong>: It inherits AutoCAD’s object snap logic with clear markers for endpoints, midpoints, circle centers, tangent points, perpendicular points, etc., enabling quick positioning of key points even in complex drawings.</p></li></ul><h3 id="_2-file-operation-data-management-module" tabindex="-1">2. File Operation &amp; Data Management Module <a class="header-anchor" href="#_2-file-operation-data-management-module" aria-label="Permalink to &quot;2\\. File Operation \\&amp; Data Management Module&quot;">​</a></h3><p>It seamlessly connects to local ecosystems, breaks the limitations of browser sandboxes, and realizes free interaction with local files: <img src="'+p+'" alt="image-20260714145126854"></p><ul><li><p><strong>Multi-Format Compatibility</strong>: It natively supports opening and saving <code>.dwg</code>, <code>.dwf</code> and <code>.dxf</code> formats. Both high and low version drawings maintain ultra-high parsing fidelity without garbled text or missing drawing elements.</p></li><li><p><strong>Cloud &amp; Local Interoperability</strong>: Beyond traditional Open/Save dialog boxes, it supports loading drawings from servers or saving to cloud databases, laying the foundation for subsequent collaborative work.</p></li></ul><h3 id="_3-view-control-layer-management-module" tabindex="-1">3. View Control &amp; Layer Management Module <a class="header-anchor" href="#_3-view-control-layer-management-module" aria-label="Permalink to &quot;3\\. View Control \\&amp; Layer Management Module&quot;">​</a></h3><p>It delivers a top-down global view and provides professional solutions for browsing and managing complex drawings: <img src="'+m+'" alt="image-20260714145348144"></p><ul><li><p><strong>Smooth View Navigation</strong>: Supports middle-mouse pan and stepless mouse-wheel zoom. The UCS icon at the bottom left reflects the current coordinate system direction in real time, and switching between Model/Layout tabs at the bottom is fluid.</p></li><li><p><strong>Fine-Grained Layer Control</strong>: It features an independent layer manager supporting layer visibility toggle, freeze, lock, as well as color and linetype configuration. Users can organize complex graphic information via layers just like in traditional CAD software.</p></li></ul><h3 id="_4-properties-panel-block-management-module" tabindex="-1">4. Properties Panel &amp; Block Management Module <a class="header-anchor" href="#_4-properties-panel-block-management-module" aria-label="Permalink to &quot;4\\. Properties Panel \\&amp; Block Management Module&quot;">​</a></h3><p>For complex block data and object organization in drawings, CAD Dream Online Drawing delivers accurate and efficient management tools to guarantee precise data entry and component calling.</p><ul><li><p><strong>Accurate Block Attribute Editing</strong> Despite its lightweight Web positioning, it makes no compromises on core data interaction. The software supports an enhanced attribute editor, allowing users to intuitively view and modify attribute tags, prompts and values inside blocks (such as equipment numbers, specifications and models). This WYSIWYG editing method enables fast entry and standardization of drawing information, meeting strict accuracy requirements for engineering drawings. <img src="'+g+'" alt="image-20260714145838383"></p></li><li><p><strong>Flexible Block Creation &amp; Management</strong> It comes with a complete block creation function, enabling users to directly define block names, specify base points and select objects for encapsulation on web pages. Whether converting common symbols into standard blocks or reorganizing existing graphics, operation logic remains consistent with desktop versions, greatly boosting drawing efficiency. <img src="'+h+'" alt="image-20260714150040244"></p></li><li><p><strong>Convenient Object Grouping Function</strong> For graphic sets that do not need to be defined as blocks but require unified management, the software provides group creation and a group manager. Users can easily combine scattered lines or text into a whole for move, copy and other operations, while also supporting ungrouping or editing internal members at any time, bringing great flexibility for organizing complex drawings. <img src="'+u+'" alt="image-20260714155252826"></p></li></ul><h3 id="_5-extension-tools-plugin-module" tabindex="-1">5. Extension Tools &amp; Plugin Module <a class="header-anchor" href="#_5-extension-tools-plugin-module" aria-label="Permalink to &quot;5\\. Extension Tools \\&amp; Plugin Module&quot;">​</a></h3><p>Beyond basic functions, CAD Dream Online Drawing boasts powerful scalability. The &quot;My Extension Tools&quot; panel as shown integrates advanced tools including multiple copy, arc to circle, circle to polygon, PI fillet, etc. This proves the platform is not merely a drawing tool, but an extensible development platform. <img src="'+f+`" alt="image-20260714160206324"></p><h2 id="iv-flexible-integration-in-depth-secondary-development" tabindex="-1">IV. Flexible Integration &amp; In-Depth Secondary Development <a class="header-anchor" href="#iv-flexible-integration-in-depth-secondary-development" aria-label="Permalink to &quot;IV\\. Flexible Integration \\&amp; In\\-Depth Secondary Development&quot;">​</a></h2><p>CAD Dream Online Drawing is not only an independent cloud CAD application, but also a powerful PaaS (Platform as a Service) development base. It provides diverse flexible integration schemes and in-depth customization capabilities for enterprises and developers, enabling seamless embedding into existing business systems and supporting secondary development based on the MxCAD kernel to meet various personalized demands.</p><h3 id="_1-two-integration-methods-for-flexible-adaptation-to-different-scenarios" tabindex="-1">1. Two Integration Methods for Flexible Adaptation to Different Scenarios <a class="header-anchor" href="#_1-two-integration-methods-for-flexible-adaptation-to-different-scenarios" aria-label="Permalink to &quot;1\\. Two Integration Methods for Flexible Adaptation to Different Scenarios&quot;">​</a></h3><p>To adapt to diverse technical architectures and business scenarios, CAD Dream Online Drawing offers two mainstream integration approaches:</p><ul><li><p><strong>NPM Package Integration</strong>: For projects adopting modern front-end frameworks (Vue, React, etc.), deep integration via NPM packages is available. Developers only need to run <code>npm install mxcad-app</code> to embed full CAD functions into their own systems like importing ordinary components. This method features low coupling and facilitates deep customization and function expansion, making it the preferred solution for implementing complex business logic. Detailed integration documentation: <a href="https://help.mxdraw.com/mxcad/zh/docs/7.BestPractice/1.MxCADAppNpmApplicationIntegration.html" target="_blank" rel="noreferrer">https://help.mxdraw.com/mxcad/zh/docs/7.BestPractice/1.MxCADAppNpmApplicationIntegration.html</a></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mxcad-app</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mxcad-app</span></span></code></pre></div></li><li><p><strong>Iframe Embedding Integration</strong>: For scenarios requiring rapid integration or minimal intrusion to existing systems, Iframe embedding is applicable. Simply provide a URL to embed CAD Dream Online Drawing as an independent application module into any web page. This method delivers fast and simple implementation, quickly equipping systems with professional CAD capabilities. Detailed integration documentation: <a href="https://help.mxdraw.com/mxcad/zh/docs/7.BestPractice/2.MxCADAPPApplicationIntegration/1.BasicDescriptionOfProjectIntegration.html" target="_blank" rel="noreferrer">https://help.mxdraw.com/mxcad/zh/docs/7.BestPractice/2.MxCADAPPApplicationIntegration/1.BasicDescriptionOfProjectIntegration.html</a></p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://mxcad.com&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Online CAD Page&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div></li></ul><h3 id="_2-in-depth-personalized-customization-to-build-exclusive-cad-experience" tabindex="-1">2. In-Depth Personalized Customization to Build Exclusive CAD Experience <a class="header-anchor" href="#_2-in-depth-personalized-customization-to-build-exclusive-cad-experience" aria-label="Permalink to &quot;2\\. In\\-Depth Personalized Customization to Build Exclusive CAD Experience&quot;">​</a></h3><p>CAD Dream Online Drawing provides abundant configuration files for enterprises to conduct thorough personalized customization, fully aligning the CAD project with corporate brand images and business workflows.</p><ul><li><p><strong>UI Interface Customization</strong>: Configuration files allow modification of application titles, Logos, theme colors (supporting light/dark mode switching), and even visibility and layout of top menu bars, left toolbars, right-click menus and other UI elements to build exclusive CAD workstations meeting corporate standards.</p></li><li><p><strong>Function &amp; Command Customization</strong>: Users can hide or display specific functional modules according to business needs, and add custom shortcut commands and aliases to optimize designers’ operation workflows and improve efficiency.</p></li><li><p><strong>Service Configuration</strong>: Backend service addresses for drawing upload, saving, printing and other operations can be flexibly configured to easily connect with internal enterprise PLM, ERP or OA systems, realizing seamless data flow between drawing data and business data.</p></li></ul><h3 id="_3-in-depth-secondary-development-based-on-mxcad-api" tabindex="-1">3. In-Depth Secondary Development Based on MxCAD API <a class="header-anchor" href="#_3-in-depth-secondary-development-based-on-mxcad-api" aria-label="Permalink to &quot;3\\. In\\-Depth Secondary Development Based on MxCAD API&quot;">​</a></h3><p>The true potential of CAD Dream Online Drawing lies in its open secondary development capabilities. Developers can directly call rich API interfaces provided by the MxCAD kernel to implement personalized functions beyond traditional CAD software.</p><ul><li><p><strong>Parametric Drawing</strong>: Scripts can be written via APIs to realize parametric and automated drawing functions. For example, input length and width parameters to generate standard drawing frames with one click; or automatically generate corresponding equipment blocks based on equipment parameters stored in databases.</p></li><li><p><strong>Business Logic Extension</strong>: CAD drawing can be deeply bound to specific businesses. For instance, develop plugins to realize two-way association between drawing graphics and enterprise BOM (Bill of Materials) databases — select graphics to view or modify their material information; or build one-click tools to count area and length and generate reports.</p></li><li><p><strong>Custom Entities &amp; Tools</strong>: For specific industries (electric power, HVAC, steel structure, etc.), exclusive drawing tools and custom entities can be developed to simplify complex drawing processes into a few simple operations, greatly boosting efficiency in professional fields.</p></li></ul><p>In summary, with flexible integration modes, in-depth customization capabilities and powerful secondary development potential, CAD Dream Online Drawing provides enterprises with a low-cost, high-efficiency graphical transformation solution. It is not only a cloud-based tool for designers, but also the core engine for enterprises to build digital design ecosystems.</p>`,43)]))}const _=i(b,[["render",w]]);export{A as __pageData,_ as default};
